# Generates the synthetic CSV corpus used by scripts/own-sweep.mjs: python3 scripts/own-corpus.py <out-dir>
# Structural edge cases (e*), number formats (n*), date formats (d*) and domain files (x*).
import csv, io, random, math, datetime as dt, os, sys
OUT = sys.argv[1]; R = random.Random(42)
def w(name, text, enc='utf-8'):
    with open(os.path.join(OUT, name), 'wb') as f: f.write(text.encode(enc) if isinstance(text, str) else text)
def rows_csv(header, rows, delim=',', eol='\n'):
    b = io.StringIO(); cw = csv.writer(b, delimiter=delim, lineterminator=eol); cw.writerow(header); cw.writerows(rows); return b.getvalue()
D0 = dt.date(2025, 1, 1)
def days(n): return [D0 + dt.timedelta(days=i) for i in range(n)]

# ── structural edge cases
w('e01-empty.csv', '')
w('e02-header-only.csv', 'Date,Region,Amount\n')
w('e03-one-row.csv', 'Date,Region,Amount\n2025-01-01,East,100\n')
w('e04-two-rows.csv', 'Date,Region,Amount\n2025-01-01,East,100\n2025-01-02,West,50\n')
w('e05-one-column-numbers.csv', 'Value\n' + '\n'.join(str(R.randint(1, 500)) for _ in range(200)))
w('e06-one-column-text.csv', 'Name\n' + '\n'.join(R.choice(['Ann', 'Bob', 'Cy', 'Di']) for _ in range(120)))
w('e07-blank-lines-crlf-bom.csv', '﻿Date,Region,Amount\r\n\r\n' + ''.join(f'{d},{R.choice("NSEW")},{R.randint(10,900)}\r\n' for d in days(90)) + '\r\n\r\n')
w('e08-trailing-delims.csv', 'Date,Region,Amount,\n' + ''.join(f'{d},{R.choice(["A","B","C"])},{R.randint(1,99)},\n' for d in days(60)))
w('e09-quoted-commas-newlines.csv', rows_csv(['Id', 'Client', 'Note', 'Amount'], [[i, R.choice(['Smith, John', 'O"Neil', 'Acme, Inc.', 'Zhang Wei']), R.choice(['ok', 'line one\nline two', 'said "hi", left', '']), R.randint(100, 5000)] for i in range(300)]))
w('e10-dup-and-empty-headers.csv', 'Date,Amount,Amount,,Region\n' + ''.join(f'{d},{R.randint(1,9)},{R.randint(1,9)},x,{R.choice("AB")}\n' for d in days(50)))
w('e11-long-unicode-headers.csv', rows_csv(['Fecha de operación', 'Région', '金额 (人民币)', '📈 Growth %', 'A very very very very very very very long column header name that goes on'], [[d.isoformat(), R.choice(['Île-de-France', 'Québec', '北京', 'São Paulo']), R.randint(1000, 90000), f'{R.uniform(-5, 9):.1f}%', R.choice(['x', 'y'])] for d in days(120)]))
w('e12-html-injection.csv', rows_csv(['Name', 'Comment', 'Score'], [[f'<b>user{i}</b>', '<script>alert(1)</script>' if i % 7 == 0 else '<img src=x onerror=alert(1)>', R.randint(1, 10)] for i in range(80)]))
w('e13-all-duplicates.csv', 'Date,Region,Amount\n' + '2025-01-01,East,100\n' * 50)
w('e14-sparse.csv', rows_csv(['Date', 'A', 'B', 'C', 'D'], [[d.isoformat()] + [R.randint(1, 9) if R.random() < 0.15 else '' for _ in range(4)] for d in days(200)]))
w('e15-wide-150.csv', rows_csv(['Id'] + [f'm{i}' for i in range(150)], [[i] + [round(R.gauss(50, 10), 2) for _ in range(150)] for i in range(300)]))
w('e16-headerless-mixed.csv', ''.join(f'{d},{R.choice(["A","B","C"])},{R.randint(1,99)}\n' for d in days(100)))
w('e17-semicolon-decimal-comma.csv', 'Datum;Filiale;Umsatz\n' + ''.join(f'{d.strftime("%d.%m.%Y")};{R.choice(["Köln","Bonn","Wien"])};{R.randint(1,9999)},{R.randint(0,99):02d}\n' for d in days(150)))
w('e18-pipe.txt', 'DATE|DESK|PNL\n' + ''.join(f'{d}|{R.choice(["Rates","FX","Credit"])}|{R.randint(-50000, 80000)}\n' for d in days(200)))
w('e19-tab.tsv', 'date\tteam\thours\n' + ''.join(f'{d}\t{R.choice(["Ops","Dev","QA"])}\t{R.uniform(0, 12):.2f}\n' for d in days(180)))
w('e20-latin1.csv', 'Ville,Catégorie,Montant\n' + ''.join(f'{R.choice(["Montréal","Trois-Rivières","Lévis"])},{R.choice(["Été","Hiver"])},{R.randint(1,999)}\n' for _ in range(100)), enc='latin-1')
w('e21-utf16.csv', 'Date\tRegion\tAmount\n' + ''.join(f'{d}\t{R.choice("NS")}\t{R.randint(1,99)}\n' for d in days(40)), enc='utf-16')
w('e22-ragged.csv', 'Date,Region,Amount\n' + ''.join(f'{d},{R.choice("AB")},{R.randint(1,99)}' + (',extra,more' if R.random() < 0.05 else '') + ('' if R.random() > 0.05 else '') + '\n' for d in days(120)) + '2025-06-01,A\n2025-06-02\n')
w('e23-title-and-footer.csv', 'Quarterly Sales Report\nGenerated by System X\n\nDate,Region,Amount\n' + ''.join(f'{d},{R.choice("NSEW")},{R.randint(10,900)}\n' for d in days(90)) + ',Total,99999\n\nEnd of report\n')
w('e24-comment-lines.csv', '# exported 2025-09-01\n# source: warehouse\nDate,Region,Amount\n' + ''.join(f'{d},{R.choice("NS")},{R.randint(1,99)}\n' for d in days(30)))

# ── number formats
def money(v): return f'${v:,.2f}' if v >= 0 else f'(${-v:,.2f})'
w('n01-currency-accounting.csv', rows_csv(['Date', 'Account', 'Amount'], [[d.isoformat(), R.choice(['Travel', 'Meals', 'Software', 'Rent']), money(R.uniform(-3000, 12000))] for d in days(240)]))
w('n02-percent.csv', rows_csv(['Month', 'Fund', 'Return'], [[f'2024-{m:02d}', f, f'{R.uniform(-4, 6):.2f}%'] for m in range(1, 13) for f in ['Alpha', 'Beta', 'Gamma']]))
w('n03-suffixes.csv', rows_csv(['Company', 'Sector', 'Revenue', 'Employees'], [[f'Co{i}', R.choice(['Tech', 'Health', 'Energy']), R.choice([f'{R.uniform(1,900):.1f}M', f'{R.uniform(1,40):.2f}B', f'{R.randint(100,999)}K']), f'{R.randint(1,90)}k'] for i in range(150)]))
w('n04-eu-thousands.csv', 'Datum;Kunde;Betrag\n' + ''.join(f'{d.strftime("%d/%m/%Y")};{R.choice(["Müller","Schmidt","Weber"])};{R.randint(1,99)}.{R.randint(100,999)},{R.randint(0,99):02d}\n' for d in days(100)))
w('n05-negatives-only.csv', rows_csv(['Date', 'Category', 'Expense'], [[d.isoformat(), R.choice(['Rent', 'Food', 'Fuel']), -R.randint(5, 900)] for d in days(150)]))
w('n06-zeros.csv', rows_csv(['Date', 'Desk', 'Amount'], [[d.isoformat(), R.choice(['A', 'B']), 0] for d in days(60)]))
w('n07-scientific.csv', rows_csv(['Sample', 'Group', 'Concentration'], [[i, R.choice(['ctrl', 'trt']), f'{R.uniform(1, 9):.3e}'] for i in range(120)]))
w('n08-huge-and-tiny.csv', rows_csv(['Date', 'Book', 'Notional'], [[d.isoformat(), R.choice(['X', 'Y']), R.choice([R.uniform(1e9, 9e12), R.uniform(0.0001, 0.01)])] for d in days(120)]))
w('n09-zip-phone-leading-zeros.csv', rows_csv(['ZIP', 'Phone', 'City', 'Customers'], [[f'0{R.randint(1000,9999)}', f'0{R.randint(100000000,999999999)}', R.choice(['Boston', 'Newark', 'Hartford']), R.randint(1, 400)] for _ in range(200)]))
w('n10-year-column.csv', rows_csv(['Year', 'Country', 'GDP'], [[y, c, round(R.uniform(100, 5000), 1)] for y in range(1990, 2025) for c in ['Canada', 'Mexico', 'USA']]))
w('n11-lat-long.csv', rows_csv(['Station', 'Latitude', 'Longitude', 'Temp'], [[f'S{i}', round(R.uniform(40, 60), 5), round(R.uniform(-130, -60), 5), round(R.gauss(12, 8), 1)] for i in range(150)]))
w('n12-int-codes.csv', rows_csv(['Code', 'Status', 'Count'], [[R.choice([100, 200, 300, 404, 500]), R.choice(['ok', 'err']), R.randint(1, 50)] for _ in range(300)]))
w('n13-bool.csv', rows_csv(['User', 'Active', 'Premium', 'Logins'], [[f'u{i}', R.choice(['TRUE', 'FALSE']), R.choice(['Y', 'N']), R.randint(0, 80)] for i in range(250)]))

# ── date formats
w('d01-us-dates.csv', rows_csv(['Date', 'Store', 'Sales'], [[d.strftime('%m/%d/%Y'), R.choice(['S1', 'S2', 'S3']), R.randint(100, 900)] for d in days(200)]))
w('d02-eu-dot-dates.csv', rows_csv(['Datum', 'Laden', 'Umsatz'], [[d.strftime('%d.%m.%Y'), R.choice(['L1', 'L2']), R.randint(100, 900)] for d in days(200)]))
w('d03-datetime.csv', rows_csv(['Timestamp', 'Level', 'Latency_ms'], [[(dt.datetime(2025, 3, 1) + dt.timedelta(minutes=7 * i)).strftime('%Y-%m-%d %H:%M:%S'), R.choice(['INFO', 'WARN', 'ERROR']), R.randint(5, 2000)] for i in range(3000)]))
w('d04-iso-tz.csv', rows_csv(['created_at', 'event', 'value'], [[(dt.datetime(2025, 1, 1) + dt.timedelta(hours=5 * i)).strftime('%Y-%m-%dT%H:%M:%SZ'), R.choice(['click', 'view', 'buy']), R.randint(1, 30)] for i in range(800)]))
w('d05-excel-serial.csv', rows_csv(['Date', 'Desk', 'Revenue'], [[45658 + i, R.choice(['A', 'B']), R.randint(100, 900)] for i in range(150)]))
w('d06-month-only.csv', rows_csv(['Month', 'Product', 'Units'], [[f'{y}-{m:02d}', p, R.randint(10, 300)] for y in (2023, 2024, 2025) for m in range(1, 13) for p in ['P1', 'P2']]))
w('d07-mon-yyyy.csv', rows_csv(['Period', 'Region', 'Revenue'], [[dt.date(2023 + (m // 12), m % 12 + 1, 1).strftime('%b %Y'), r, R.randint(1000, 9000)] for m in range(30) for r in ['NA', 'EU']]))
w('d08-quarters.csv', rows_csv(['Quarter', 'Segment', 'Revenue'], [[f'{y}Q{q}', s, R.randint(100, 900)] for y in (2022, 2023, 2024, 2025) for q in range(1, 5) for s in ['Retail', 'Inst']]))
w('d09-single-day.csv', rows_csv(['Date', 'Trader', 'PnL'], [['2025-05-05', R.choice(['T1', 'T2', 'T3']), R.randint(-900, 900)] for _ in range(100)]))
w('d10-two-days.csv', rows_csv(['Date', 'Trader', 'PnL'], [[R.choice(['2025-05-05', '2025-05-06']), R.choice(['T1', 'T2', 'T3']), R.randint(-900, 900)] for _ in range(100)]))
w('d11-century-span.csv', rows_csv(['Date', 'Event', 'Count'], [[dt.date(1901 + i, 6, 1).isoformat(), R.choice(['flood', 'drought']), R.randint(1, 20)] for i in range(124)]))
w('d12-gappy-series.csv', rows_csv(['Date', 'Desk', 'Revenue'], [[d.isoformat(), R.choice(['A', 'B']), R.randint(1, 99)] for d in days(400) if (d.month not in (3, 4, 9))]))
w('d13-10yr-daily.csv', rows_csv(['Date', 'Close', 'Volume'], [[(dt.date(2015, 1, 1) + dt.timedelta(days=i)).isoformat(), round(100 + i * 0.03 + R.gauss(0, 2), 2), R.randint(100000, 9000000)] for i in range(3650)]))
w('d14-hourly-one-day.csv', rows_csv(['Time', 'Sensor', 'Reading'], [[f'2025-07-01 {h:02d}:{m:02d}', R.choice(['a', 'b']), round(R.uniform(10, 30), 2)] for h in range(24) for m in (0, 15, 30, 45)]))
w('d15-mixed-date-formats.csv', rows_csv(['Date', 'Region', 'Amount'], [[R.choice([d.isoformat(), d.strftime('%m/%d/%Y'), d.strftime('%d-%b-%Y')]), R.choice('NS'), R.randint(1, 99)] for d in days(150)]))
w('d16-future-dates.csv', rows_csv(['Due', 'Client', 'Amount'], [[(dt.date(2026, 1, 1) + dt.timedelta(days=3 * i)).isoformat(), R.choice(['C1', 'C2', 'C3']), R.randint(100, 900)] for i in range(200)]))
w('d17-time-only.csv', rows_csv(['Time', 'Line', 'Units'], [[f'{h:02d}:{m:02d}', R.choice(['L1', 'L2']), R.randint(1, 40)] for h in range(8, 18) for m in range(0, 60, 10)]))

# ── domains
cl = [f'Client {c}' for c in 'ABCDEFGHIJKLMNOPQRSTUVWXYZ']
w('x01-trades.csv', rows_csv(['TradeID', 'TradeDate', 'Client', 'Desk', 'Side', 'Notional', 'Revenue', 'Status'], [[f'T{100000+i}', (D0 + dt.timedelta(days=R.randint(0, 270))).isoformat(), R.choice(cl), R.choice(['Rates', 'Credit', 'FX', 'Equities']), R.choice(['Buy', 'Sell']), R.randint(1, 500) * 10000, round(R.lognormvariate(7, 1.2), 2), R.choice(['Executed'] * 9 + ['Cancelled'])] for i in range(20000)]))
w('x02-fx-rates.csv', rows_csv(['Date', 'Pair', 'Rate'], [[d.isoformat(), p, round(b * (1 + R.gauss(0, 0.004)), 5)] for d in days(365) for p, b in [('EURUSD', 1.08), ('USDJPY', 150), ('USDCAD', 1.36)]]))
w('x03-balances.csv', rows_csv(['AsOf', 'Account', 'Balance'], [[d.isoformat(), a, round(R.uniform(1000, 90000), 2)] for d in days(120) for a in ['Chequing', 'Savings', 'Brokerage']]))
w('x04-survey-likert.csv', rows_csv(['RespondentID', 'Submitted', 'Department', 'Q1_Satisfaction', 'Q2_Recommend', 'Comments'], [[i, (D0 + dt.timedelta(days=R.randint(0, 60))).isoformat(), R.choice(['Sales', 'Ops', 'Tech', 'HR']), R.randint(1, 5), R.choice(['Strongly agree', 'Agree', 'Neutral', 'Disagree']), R.choice(['', 'Great team', 'Too many meetings', 'N/A', 'More training please'])] for i in range(400)]))
w('x05-web-logs.csv', rows_csv(['ts', 'ip', 'method', 'path', 'status', 'bytes', 'ms'], [[(dt.datetime(2025, 8, 1) + dt.timedelta(seconds=37 * i)).isoformat(), f'10.0.{R.randint(0,9)}.{R.randint(1,254)}', R.choice(['GET'] * 8 + ['POST']), R.choice(['/', '/api/a', '/api/b', '/login']), R.choice([200] * 20 + [301, 404, 500]), R.randint(200, 90000), R.randint(2, 900)] for i in range(10000)]))
w('x06-inventory.csv', rows_csv(['SKU', 'Product', 'Category', 'Warehouse', 'OnHand', 'UnitCost'], [[f'SKU-{i:05d}', f'Item {i}', R.choice(['Tools', 'Garden', 'Kitchen']), R.choice(['TOR', 'MTL', 'VAN']), R.randint(0, 500), round(R.uniform(1, 200), 2)] for i in range(1200)]))
w('x07-hr.csv', rows_csv(['EmployeeID', 'Name', 'HireDate', 'Department', 'Level', 'Salary', 'Manager'], [[f'E{i:04d}', f'Person {i}', (dt.date(2010, 1, 1) + dt.timedelta(days=R.randint(0, 5500))).isoformat(), R.choice(['Eng', 'Sales', 'Fin', 'Ops']), R.choice(['L1', 'L2', 'L3', 'L4']), R.randint(55, 240) * 1000, f'E{R.randint(0, 50):04d}'] for i in range(600)]))
w('x08-crypto-ohlc.csv', rows_csv(['date', 'open', 'high', 'low', 'close', 'volume'], [[d.isoformat(), *(lambda o: [o, o * 1.03, o * 0.97, o * (1 + R.gauss(0, 0.02))])(round(30000 + i * 40 + R.gauss(0, 800), 2)), R.randint(1000000, 900000000)] for i, d in enumerate(days(500))]))
w('x09-weather.csv', rows_csv(['date', 'city', 'tmax', 'tmin', 'precip_mm'], [[d.isoformat(), c, round(15 + 12 * math.sin(i / 58) + R.gauss(0, 3), 1), round(5 + 10 * math.sin(i / 58) + R.gauss(0, 3), 1), max(0, round(R.gauss(1, 4), 1))] for i, d in enumerate(days(730)) for c in ['Toronto', 'Vancouver']]))
w('x10-orders-messy.csv', rows_csv(['Order #', 'Order Date', 'Customer', 'Country', 'Qty', 'Price', 'Total'], [[f'#{1000+i}', R.choice([(D0 + dt.timedelta(days=R.randint(0, 200))).isoformat(), 'TBD', '']), R.choice(['acme', 'ACME', 'Acme ', 'Globex', 'Initech']), R.choice(['CA', 'Canada', 'US', 'USA', 'U.S.']), R.choice([R.randint(1, 20), 'n/a']), round(R.uniform(5, 300), 2), R.choice([round(R.uniform(5, 3000), 2), '', '#VALUE!', 9999999])] for i in range(700)]))
w('x11-budget-vs-actual.csv', rows_csv(['Month', 'Department', 'Budget', 'Actual', 'Variance'], [[f'2025-{m:02d}', d, b := R.randint(10000, 90000), a := int(b * R.uniform(0.7, 1.3)), a - b] for m in range(1, 10) for d in ['Marketing', 'IT', 'Legal', 'Facilities']]))
w('x12-gl-journal.csv', rows_csv(['JE', 'PostDate', 'Account', 'Debit', 'Credit', 'Memo'], [[f'JE{i}', (D0 + dt.timedelta(days=R.randint(0, 300))).isoformat(), R.choice(['1000 Cash', '2000 AP', '4000 Revenue', '5000 COGS']), R.choice([round(R.uniform(10, 9000), 2), '']), R.choice([round(R.uniform(10, 9000), 2), '']), R.choice(['accrual', 'reclass', 'payment', ''])] for i in range(1500)]))
w('x13-kyc-clients.csv', rows_csv(['LEI', 'Client Name', 'Country', 'Risk Rating', 'Onboarded', 'Last Review', 'Status'], [[''.join(R.choice('ABCDEFGHJKLMNPQRSTUVWXYZ0123456789') for _ in range(20)), f'Entity {i}', R.choice(['CA', 'US', 'GB', 'DE', 'SG']), R.choice(['Low', 'Medium', 'High']), (dt.date(2015, 1, 1) + dt.timedelta(days=R.randint(0, 3600))).isoformat(), R.choice([(dt.date(2023, 1, 1) + dt.timedelta(days=R.randint(0, 900))).isoformat(), '']), R.choice(['Active', 'Pending', 'Closed'])] for i in range(900)]))
w('x14-tall-200k.csv', rows_csv(['Date', 'Region', 'Product', 'Amount'], [[(D0 + dt.timedelta(days=i % 365)).isoformat(), R.choice('NSEW'), R.choice(['A', 'B', 'C', 'D', 'E']), R.randint(1, 999)] for i in range(205000)]))
w('x15-high-card-dim.csv', rows_csv(['Date', 'Customer', 'Amount'], [[(D0 + dt.timedelta(days=R.randint(0, 99))).isoformat(), f'Cust{R.randint(1, 900)}', R.randint(1, 99)] for _ in range(2000)]))
w('x16-one-value-dim.csv', rows_csv(['Date', 'Country', 'Amount'], [[d.isoformat(), 'Canada', R.randint(1, 99)] for d in days(100)]))
w('x17-text-heavy.csv', rows_csv(['Ticket', 'Opened', 'Priority', 'Description'], [[f'INC{i}', (D0 + dt.timedelta(days=R.randint(0, 90))).isoformat(), R.choice(['P1', 'P2', 'P3']), ' '.join(R.choice(['server', 'down', 'slow', 'login', 'error', 'user', 'cannot', 'access', 'report', 'timeout']) for _ in range(R.randint(5, 30)))] for i in range(500)]))
w('x18-pivoted-wide-months.csv', rows_csv(['Region', 'Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Total'], [[r] + (vals := [R.randint(100, 900) for _ in range(6)]) + [sum(vals)] for r in ['North', 'South', 'East', 'West', 'Central']]))
print(len(os.listdir(OUT)))
